/**
 * Shows per-activity type names ("Dropbox") and personal titles ("Coach") on course pages, and adds the
 * "Post a new ..." buttons in editing mode. Only display text changes; module types and roles stay the same.
 *
 * @module     local_materialtools/labels
 * @copyright  2026 Ding Ding Projects
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_materialtools/labels', [], function() {
    var data = {};

    /**
     * Replace whole-word occurrences of a word inside an element's text nodes.
     *
     * @param {HTMLElement} root
     * @param {string} from
     * @param {string} to
     */
    function replaceWord(root, from, to) {
        if (!root || !from || !to || from === to) {
            return;
        }
        var re = new RegExp('(^|[^\\p{L}])(' + from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')(?![\\p{L}])', 'giu');
        var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        var nodes = [];
        while (walker.nextNode()) {
            nodes.push(walker.currentNode);
        }
        nodes.forEach(function(n) {
            var next = n.nodeValue.replace(re, function(m, pre) {
                return pre + to;
            });
            if (next !== n.nodeValue) {
                n.nodeValue = next;
            }
        });
    }

    /**
     * Type chips and hidden type text on course pages.
     */
    function activities() {
        Object.keys(data.labels || {}).forEach(function(cmid) {
            var label = data.labels[cmid];
            document.querySelectorAll('[data-for="cmitem"][data-id="' + cmid + '"], #module-' + cmid).forEach(function(item) {
                if (item.dataset.mdLabelled) {
                    return;
                }
                item.dataset.mdLabelled = '1';
                item.querySelectorAll('.activityname .accesshide, .instancename .accesshide, .activitytype, .activity-type')
                    .forEach(function(t) {
                        t.textContent = ' ' + label;
                    });
                var name = item.querySelector('.activityname, .activity-name-area, .instancename');
                if (name && !item.querySelector('.md-type-chip')) {
                    var chip = document.createElement('span');
                    chip.className = 'md-type-chip';
                    chip.textContent = label;
                    name.parentNode.insertBefore(chip, name);
                }
            });
        });
        if (data.cmid && data.labels && data.labels[data.cmid] && data.modname) {
            var label = data.labels[data.cmid];
            ['#page-header', '.activity-header', '#page-navbar', '.breadcrumb', '.page-context-header']
                .forEach(function(sel) {
                    document.querySelectorAll(sel).forEach(function(el) {
                        replaceWord(el, data.modname, label);
                    });
                });
            document.title = document.title.replace(data.modname, label);
        }
    }

    /**
     * Personal titles beside people.
     */
    function people() {
        var titles = data.titles || {};
        Object.keys(titles).forEach(function(userid) {
            var title = titles[userid];
            // Participants page role cells.
            document.querySelectorAll('[data-component="core_role"][data-itemid$=":' + userid + '"]').forEach(function(cell) {
                if (cell.dataset.mdTitled) {
                    return;
                }
                cell.dataset.mdTitled = '1';
                var shown = cell.querySelector('[data-region="role-display"], .quickeditlink') || cell;
                var text = Array.prototype.find.call(shown.childNodes, function(n) {
                    return n.nodeType === 3 && n.nodeValue.trim();
                });
                if (text) {
                    text.nodeValue = title;
                } else {
                    shown.insertBefore(document.createTextNode(title), shown.firstChild);
                }
                cell.title = title;
            });
            // Course contacts ("Teacher: Name").
            document.querySelectorAll('.teachers li, .course-contacts li, .coursebox .teachers li').forEach(function(li) {
                var link = li.querySelector('a[href*="id=' + userid + '"]');
                if (!link || li.dataset.mdTitled) {
                    return;
                }
                li.dataset.mdTitled = '1';
                var first = li.firstChild;
                if (first && first.nodeType === 3 && first.nodeValue.indexOf(':') !== -1) {
                    first.nodeValue = title + ': ';
                }
            });
            // A small title chip after names in forum posts and profile headers.
            document.querySelectorAll('.page-context-header a[href*="user/view.php?id=' + userid + '"], ' +
                    '[data-region="post"] header a[href*="user/view.php?id=' + userid + '&"]').forEach(function(a) {
                if (a.nextElementSibling && a.nextElementSibling.classList.contains('md-title-chip')) {
                    return;
                }
                var chip = document.createElement('span');
                chip.className = 'md-title-chip';
                chip.textContent = title;
                a.insertAdjacentElement('afterend', chip);
            });
        });
    }

    /**
     * "Post a new Dropbox" buttons at the top of the course in editing mode.
     */
    function quickPosts() {
        if (!data.quickposts || !data.quickposts.length || document.querySelector('.md-quick-posts')) {
            return;
        }
        var host = document.querySelector('#region-main .course-content, #region-main [data-region="course-content"]');
        if (!host) {
            return;
        }
        var bar = document.createElement('div');
        bar.className = 'md-quick-posts';
        data.quickposts.forEach(function(p) {
            var a = document.createElement('a');
            a.className = 'btn btn-secondary';
            a.href = p.url;
            a.textContent = (data.strings.postnew || 'Post a new {$a}').replace('{$a}', p.label);
            bar.appendChild(a);
        });
        if (data.newposttypeurl) {
            var add = document.createElement('a');
            add.className = 'btn btn-outline-secondary';
            add.href = data.newposttypeurl;
            add.textContent = data.strings.newposttype || 'New quick post type';
            bar.appendChild(add);
        }
        host.parentNode.insertBefore(bar, host);
    }

    /**
     * Apply everything.
     */
    function run() {
        activities();
        people();
        quickPosts();
    }

    return {
        /**
         * Start.
         *
         * @param {Object} config
         */
        init: function(config) {
            data = config || {};
            run();
            var timer = null;
            new MutationObserver(function() {
                clearTimeout(timer);
                timer = setTimeout(run, 60);
            }).observe(document.body, {childList: true, subtree: true});
        }
    };
});
